// --- Microphone Permission Handling & Re-grant Logic ---
const micPermissionModal = document.getElementById('mic-permission-modal');
grantMicPermBtn = document.getElementById('grant-mic-perm-btn');
closeMicPermBtn = document.getElementById('close-mic-perm-btn');
callMicWarningBtn = document.getElementById('call-mic-warning-btn');
const micPermDesc = document.getElementById('mic-perm-desc');

let isMicPermissionBlocked = false;

function showMicPermissionModal(message) {
  isMicPermissionBlocked = true;
  if (micPermDesc && message) micPermDesc.textContent = message;
  if (micPermissionModal) micPermissionModal.classList.remove('hidden');
  if (callMicWarningBtn) callMicWarningBtn.classList.remove('hidden');
}

function hideMicPermissionModal() {
  if (micPermissionModal) micPermissionModal.classList.add('hidden');
}

async function requestAndEnableMicrophone() {
  try {
    console.log('[Media] Requesting microphone permission from browser...');
    const freshStream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true }
    });

    const newAudioTrack = freshStream.getAudioTracks()[0];
    if (!newAudioTrack) throw new Error('No audio track returned');

    console.log('[Media] Microphone permission granted by user!');
    isMicPermissionBlocked = false;
    hideMicPermissionModal();
    if (callMicWarningBtn) callMicWarningBtn.classList.add('hidden');

    // If currently in a call, bind this new track to localStream & StreamEngine peerConnection!
    if (localStream) {
      // Stop old dead audio tracks
      localStream.getAudioTracks().forEach(t => {
        t.stop();
        localStream.removeTrack(t);
      });
      localStream.addTrack(newAudioTrack);
    } else {
      localStream = freshStream;
    }

    if (peerConnection) {
      const senders = peerConnection.getSenders();
      const audioSender = senders.find(s => s.track && s.track.kind === 'audio');
      if (audioSender) {
        await audioSender.replaceTrack(newAudioTrack);
        console.log('[StreamEngine] Replaced StreamEngine audio track with new granted microphone track.');
      } else {
        peerConnection.addTrack(newAudioTrack, localStream);
        console.log('[StreamEngine] Added new microphone track to active peer connection.');
      }
    }

    isMicMuted = false;
    if (iosMuteBtn) iosMuteBtn.classList.remove('muted');
    if (iosMuteLabel) iosMuteLabel.textContent = 'Mute';
    if (activeCallStatus) {
      activeCallStatus.textContent = callType === 'video' ? 'Video Call Active ✓' : 'Voice Call Active ✓';
    }

    alert('🎙️ Microphone access granted! Your voice is now transmitting.');
    return freshStream;

  } catch (err) {
    console.warn('[Media] Microphone re-grant attempt failed:', err.name, err.message);
    isMicPermissionBlocked = true;
    if (callMicWarningBtn) callMicWarningBtn.classList.remove('hidden');

    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
      showMicPermissionModal('Microphone permission is blocked in your browser site settings. Follow the instructions below to enable it.');
    } else {
      alert(`⚠️ Could not access microphone: ${err.message || 'Permission denied'}`);
    }
    return null;
  }
}

if (grantMicPermBtn) grantMicPermBtn.addEventListener('click', requestAndEnableMicrophone);
if (closeMicPermBtn) closeMicPermBtn.addEventListener('click', hideMicPermissionModal);
if (callMicWarningBtn) callMicWarningBtn.addEventListener('click', () => {
  requestAndEnableMicrophone();
});

// Auto-detect permission status changes in modern browsers
try {
  if (navigator.permissions && typeof navigator.permissions.query === 'function') {
    navigator.permissions.query({ name: 'microphone' }).then(perm => {
      perm.onchange = () => {
        console.log('[Permissions API] Microphone state changed to:', perm.state);
        if (perm.state === 'granted') {
          if (isMicPermissionBlocked || (peerConnection && localStream && localStream.getAudioTracks().length === 0)) {
            requestAndEnableMicrophone();
          }
        } else if (perm.state === 'denied') {
          isMicPermissionBlocked = true;
          if (callMicWarningBtn) callMicWarningBtn.classList.remove('hidden');
        }
      };
    }).catch(() => {});
  }
} catch (e) {}

// Camera switching logic for switching between front/back camera
async function switchCamera() {
  if (!localStream || callType !== 'video') return;

  // Toggle active facing mode
  currentFacingMode = (currentFacingMode === 'user') ? 'environment' : 'user';
  console.log(`Switching camera facingMode to: ${currentFacingMode}`);
  logDiagnostic(`Switching camera: ${currentFacingMode}...`);

  try {
    const oldVideoTrack = localStream.getVideoTracks()[0];
    
    // Stop the old camera track first to release camera lock on some Android browsers
    if (oldVideoTrack) {
      localStream.removeTrack(oldVideoTrack);
      oldVideoTrack.stop();
    }

    // Request new video stream with the updated facingMode constraint
    const newStream = await navigator.mediaDevices.getUserMedia({
      audio: true,
      video: { facingMode: currentFacingMode }
    });

    const newVideoTrack = newStream.getVideoTracks()[0];
    if (!newVideoTrack) {
      throw new Error("No video track found in the new camera stream.");
    }
    
    // Add new camera track to local stream
    localStream.addTrack(newVideoTrack);

    // Swap source object for local video tag
    localVideo.srcObject = localStream;

    // replaceTrack StreamEngine sender to update peer side stream in real time
    if (peerConnection) {
      const senders = peerConnection.getSenders();
      const videoSender = senders.find(s => s.track && s.track.kind === 'video');
      if (videoSender) {
        await videoSender.replaceTrack(newVideoTrack);
      }
      
      // Force an SDP renegotiation to update hardware video encoder pipelines on mobile
      try {
        logDiagnostic("Renegotiating session...");
        const offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        socket.emit('call-user', {
          to: activeCallTargetSocketId,
          offer: offer,
          type: callType
        });
      } catch (negErr) {
        console.warn("Failed to create renegotiation offer:", negErr);
      }
    }

    
    logDiagnostic(`Switched to ${currentFacingMode} camera`);

  } catch (err) {
    console.error('Camera switch failed:', err);
    logDiagnostic('Camera switch failed.');
    
    // Try to fallback by recovering default camera
    try {
      const fallbackStream = await navigator.mediaDevices.getUserMedia({
        audio: true,
        video: true
      });
      const newVideoTrack = fallbackStream.getVideoTracks()[0];
      localStream.addTrack(newVideoTrack);
      localVideo.srcObject = localStream;
      if (peerConnection) {
        const senders = peerConnection.getSenders();
        const videoSender = senders.find(s => s.track && s.track.kind === 'video');
        if (videoSender) await videoSender.replaceTrack(newVideoTrack);
      }
    } catch (e) {
      console.error('Camera recovery failed:', e);
    }
    alert('Failed to switch camera source.');
  }
}


if (switchCameraBtn) {
  switchCameraBtn.addEventListener('click', switchCamera);
}

// Dynamic video quality toggling between High Quality (HD) and Low Quality (SD)
async function toggleVideoQuality() {
  if (!localStream || callType !== 'video') return;
  const videoTrack = localStream.getVideoTracks()[0];
  if (!videoTrack) return;

  isHighQuality = !isHighQuality;

  // HQ constraints: 720p 30fps. LQ constraints: 360p 15fps. Both maintain 16:9 aspect ratio to prevent zoom shifts.
  const constraints = isHighQuality 
    ? { width: { ideal: 1280 }, height: { ideal: 720 }, aspectRatio: 1.777777778, frameRate: { ideal: 30 } }
    : { width: { ideal: 640 }, height: { ideal: 360 }, aspectRatio: 1.777777778, frameRate: { ideal: 15 } };


  try {
    await videoTrack.applyConstraints(constraints);
    console.log(`Video quality constraints applied. High Quality: ${isHighQuality}`);
    
    // Force an SDP renegotiation to update hardware video encoder pipelines on mobile
    if (peerConnection) {
      try {
        logDiagnostic("Renegotiating session...");
        const offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        socket.emit('call-user', {
          to: activeCallTargetSocketId,
          offer: offer,
          type: callType
        });
      } catch (negErr) {
        console.warn("Failed to create renegotiation offer:", negErr);
      }
    }

    
    if (isHighQuality) {

      if (qualityBtnLabel) qualityBtnLabel.textContent = 'HD';
      if (toggleQualityBtn) {
        toggleQualityBtn.classList.remove('low-bandwidth');
        toggleQualityBtn.title = 'Switch to Low Quality (SD)';
      }
      alert('Video quality switched to High Definition (720p HD).');
    } else {
      if (qualityBtnLabel) qualityBtnLabel.textContent = 'SD';
      if (toggleQualityBtn) {
        toggleQualityBtn.classList.add('low-bandwidth');
        toggleQualityBtn.title = 'Switch to High Quality (HD)';
      }
      alert('Video quality switched to Low Bandwidth (180p SD) to save network data.');
    }
  } catch (err) {
    console.error('Failed to apply video constraints:', err);
    isHighQuality = !isHighQuality; // Revert state
    alert('Dynamic video resolution constraint switching is not supported on this device.');
  }
}

if (toggleQualityBtn) {
  toggleQualityBtn.addEventListener('click', toggleVideoQuality);
}

// Automatically resume/play remote video when its stream resolution changes (SD <-> HD)
