// Update Direct Message active header sub-text
function updateHeaderDMStatus() {
  if (!currentRoom.startsWith('dm:')) return;
  const parts = currentRoom.split(':');
  const peerName = (currentUsername === parts[1]) ? parts[2] : parts[1];

  const peer = globalUsersList.find(u => u.username === peerName);
  if (peer) {
    if (peer.status === 'online') {
      roomMembersCount.textContent = 'online';
      roomMembersCount.style.color = 'var(--accent-color)';
    } else {
      roomMembersCount.textContent = formatLastSeen(peer.lastSeen);
      roomMembersCount.style.color = 'var(--text-muted)';
    }
  }
}

function formatLastSeen(timestamp) {
  const diffMs = Date.now() - new Date(timestamp).getTime();
  const diffMins = Math.floor(diffMs / 60000);
  if (diffMins < 1) return 'last seen just now';
  if (diffMins < 60) return `last seen ${diffMins}m ago`;
  const diffHrs = Math.floor(diffMins / 60);
  if (diffHrs < 24) return `last seen ${diffHrs}h ago`;
  const diffDays = Math.floor(diffHrs / 24);
  return `last seen ${diffDays}d ago`;
}

// Switch Room Controller Helper
function switchChatRoom(roomName) {
  if (roomName === currentRoom) {
    if (window.innerWidth <= 768) {
      document.body.classList.add('active-chat');
    }
    return;
  }

  // Switch active classes in roomsList channels
  roomsList.querySelectorAll('.room-item').forEach(ri => {
    if (ri.getAttribute('data-room') === roomName) {
      ri.classList.add('active');
    } else {
      ri.classList.remove('active');
    }
  });

  // Switch selection in user DMs sidebar
  onlineUsersList.querySelectorAll('.user-item').forEach(ui => {
    const nameText = ui.querySelector('.user-name-list').textContent;
    const name = nameText.replace(' (you)', '').trim();
    const dmRoom = getDMRoomName(currentUsername, name);
    
    if (dmRoom === roomName) {
      ui.classList.add('active');
    } else {
      ui.classList.remove('active');
    }
  });

  currentRoom = roomName;

  // Clear unread badge counts
  unreadMessageCounts.delete(currentRoom);

  // Clear typing indications
  activeTypingUsers.clear();
  updateTypingIndicator();

  // Reset Input states
  messageInput.value = '';
  sendBtn.classList.add('hidden');
  micRecordBtn.classList.remove('hidden');

  // Load UI Headers
  const isDM = roomName.startsWith('dm:');
  const isCodeRoom = roomName.startsWith('code-');

  if (isDM || isCodeRoom) {
    if (headerCallActions) {
      headerCallActions.classList.remove('hidden');
      headerCallActions.classList.add('active-private-session');
    }
    if (isDM) {
      const parts = roomName.split(':');
      const peerName = (currentUsername === parts[1]) ? parts[2] : parts[1];
      activeRoomTitle.textContent = peerName;
      selfDestructControl.classList.remove('hidden');
      updateHeaderDMStatus();
    } else {
      // Code Room
      const displayName = `Private: ${roomName.replace('code-', '')}`;
      activeRoomTitle.textContent = displayName;
      roomMembersCount.textContent = '0 online';
      currentRoomUsers = []; // Reset occupants until room-users list is received
      selfDestructControl.classList.add('hidden');
    }
  } else {
    activeRoomTitle.textContent = roomName;
    roomMembersCount.textContent = 'Connecting...';
    
    if (headerCallActions) {
      headerCallActions.classList.add('hidden');
      headerCallActions.classList.remove('active-private-session');
    }
    selfDestructControl.classList.add('hidden');
  }


  if (socket) {
    socket.emit('join-room', {
      username: currentUsername,
      room: currentRoom
    });
    
    // Mark as read immediately on open
    socket.emit('mark-read', { room: currentRoom, username: currentUsername });
  }

  // Slide over on mobile layouts
  if (window.innerWidth <= 768) {
    document.body.classList.add('active-chat');
  }
}

// --- Create Custom Channel Action ---
createRoomBtn = document.getElementById('create-room-btn');
if (createRoomBtn) {
  createRoomBtn.addEventListener('click', () => {
    const name = prompt('Enter a name for the new chat channel:');
    if (!name) return;
    const trimmed = name.trim();
    if (trimmed.length === 0) return;
    
    if (socket) {
      socket.emit('create-room', { room: trimmed });
      // Switch to it immediately after server updates
      setTimeout(() => {
        switchChatRoom(trimmed);
      }, 300);
    }
  });
}

// --- Create Secret Code Room ---
createCodeRoomBtn = document.getElementById('create-code-room-btn');
if (createCodeRoomBtn) {
  createCodeRoomBtn.addEventListener('click', () => {
    // Generate a random 6-digit room code
    const code = Math.floor(100000 + Math.random() * 900000);
    const roomName = `code-${code}`;
    
    if (socket) {
      // Create secret room on the server (doesn't broadcast to other people's sidebar)
      socket.emit('create-room', { room: roomName, isSecret: true });
      
      // Save it locally for the current user
      let localRooms = JSON.parse(localStorage.getItem('joined-code-rooms') || '[]');
      if (!localRooms.includes(roomName)) {
        localRooms.push(roomName);
        localStorage.setItem('joined-code-rooms', JSON.stringify(localRooms));
      }
      
      alert(`🔑 Private Room Created!\n\nYour Room Code is: ${code}\n\nShare this code with another user to let them join your private room. Clicking OK will switch you into the room.`);
      switchChatRoom(roomName);
    }
  });
}

// --- Join Secret Code Room ---
joinCodeRoomBtn = document.getElementById('join-code-room-btn');
if (joinCodeRoomBtn) {
  joinCodeRoomBtn.addEventListener('click', () => {
    const input = prompt('Enter the secure 6-digit room code:');
    if (!input) return;
    const code = input.trim();
    if (code.length === 0) return;
    
    const roomName = `code-${code}`;
    
    // Save it locally for the current user
    let localRooms = JSON.parse(localStorage.getItem('joined-code-rooms') || '[]');
    if (!localRooms.includes(roomName)) {
      localRooms.push(roomName);
      localStorage.setItem('joined-code-rooms', JSON.stringify(localRooms));
    }
    
    if (socket) {
      // Join the room on the server
      socket.emit('join-room', {
        username: currentUsername,
        room: roomName,
        metadata: getClientMetadata()
      });
    }
    
    switchChatRoom(roomName);
  });
}

// ============================================================
// AETHER FEATURES: Context Menu, Reply, Edit, Delete, React
// ============================================================

const msgContextMenu = document.getElementById('msg-context-menu');
const replyPreviewBar = document.getElementById('reply-preview-bar');
const editModeBar = document.getElementById('edit-mode-bar');
const pinnedMessageBar = document.getElementById('pinned-message-bar');
const emojiPickerPanel = document.getElementById('emoji-picker-panel');
const forwardModal = document.getElementById('forward-modal');

function showContextMenu(e, msgData, isOwn) {
  e.preventDefault();
  contextMenuTargetMsg = msgData;
  document.getElementById('ctx-edit').classList.toggle('hidden', !isOwn || !!msgData.file);
  document.getElementById('ctx-delete').classList.toggle('hidden', !isOwn);
  msgContextMenu.classList.remove('hidden');
  const x = Math.min(e.clientX, window.innerWidth - 180);
  const y = Math.min(e.clientY, window.innerHeight - msgContextMenu.offsetHeight - 10);
  msgContextMenu.style.left = x + 'px';
  msgContextMenu.style.top = y + 'px';
}

document.addEventListener('click', () => msgContextMenu.classList.add('hidden'));
msgContextMenu.addEventListener('click', (e) => e.stopPropagation());

// Reply message trigger
function startReply(msg) {
  activeReplyMsg = msg;
  activeEditMsgId = null;
  editModeBar.classList.add('hidden');
  replyPreviewBar.classList.remove('hidden');
  document.getElementById('reply-preview-name').textContent = msg.username;
  document.getElementById('reply-preview-text').textContent = msg.text || '[File]';
  messageInput.focus();
}

document.getElementById('cancel-reply-btn').addEventListener('click', () => {
  activeReplyMsg = null;
  replyPreviewBar.classList.add('hidden');
});

// Edit message trigger
function startEdit(msg) {
  activeEditMsgId = msg.id;
  activeReplyMsg = null;
  replyPreviewBar.classList.add('hidden');
  editModeBar.classList.remove('hidden');
  document.getElementById('edit-preview-text').textContent = msg.text;
  messageInput.value = msg.text;
  messageInput.focus();
  
  // Show send button
  sendBtn.classList.remove('hidden');
  micRecordBtn.classList.add('hidden');
}

document.getElementById('cancel-edit-btn').addEventListener('click', () => {
  activeEditMsgId = null;
  editModeBar.classList.add('hidden');
  messageInput.value = '';
  sendBtn.classList.add('hidden');
  micRecordBtn.classList.remove('hidden');
});

// Delete message manual trigger
function deleteMessageForEveryone(msgId) {
  if (!confirm('Delete this message for everyone?')) return;
  socket.emit('delete-message-manual', { room: currentRoom, messageId: msgId });
}

// React to a message
function sendReaction(msgId, emoji) {
  socket.emit('react-message', { room: currentRoom, messageId: msgId, emoji });
}

// Pin a message
function pinMessage(msgId) {
  socket.emit('pin-message', { room: currentRoom, messageId: msgId });
}

// Forward modal and actions
let forwardMsgId = null;
function showForwardModal(msgId) {
  forwardMsgId = msgId;
  const list = document.getElementById('forward-rooms-list');
  list.innerHTML = '';
  
  const allRooms = [...roomsList.querySelectorAll('.room-item')].map(li => li.getAttribute('data-room')).filter(Boolean);
  if (allRooms.length <= 1) {
    list.innerHTML = '<p style="color:var(--text-muted);font-size:0.8rem;text-align:center;padding:10px;">No other rooms available.</p>';
  }
  
  allRooms.forEach(room => {
    if (room === currentRoom) return;
    const btn = document.createElement('button');
    btn.className = 'forward-room-item';
    btn.type = 'button';
    btn.innerHTML = `<div class="forward-room-avatar">${room.substring(0, 2).toUpperCase()}</div><span>${escapeHTML(room)}</span>`;
    btn.addEventListener('click', () => {
      socket.emit('forward-message', {
        fromRoom: currentRoom,
        toRoom: room,
        messageId: forwardMsgId
      });
      forwardModal.classList.add('hidden');
      alert(`Message forwarded to "${room}"!`);
    });
    list.appendChild(btn);
  });
  
  forwardModal.classList.remove('hidden');
}

document.getElementById('forward-modal-close').addEventListener('click', () => {
  forwardModal.classList.add('hidden');
});

forwardModal.addEventListener('click', (e) => {
  if (e.target === forwardModal) forwardModal.classList.add('hidden');
});

// Bind Context Menu Items actions
document.getElementById('ctx-reply').addEventListener('click', () => {
  if (contextMenuTargetMsg) startReply(contextMenuTargetMsg);
});
document.getElementById('ctx-edit').addEventListener('click', () => {
  if (contextMenuTargetMsg) startEdit(contextMenuTargetMsg);
});
document.getElementById('ctx-copy').addEventListener('click', () => {
  if (contextMenuTargetMsg?.text) {
    navigator.clipboard.writeText(contextMenuTargetMsg.text)
      .then(() => alert('Copied to clipboard!'))
      .catch(() => {});
  }
});
document.getElementById('ctx-forward').addEventListener('click', () => {
  if (contextMenuTargetMsg) showForwardModal(contextMenuTargetMsg.id);
});
document.getElementById('ctx-pin').addEventListener('click', () => {
  if (contextMenuTargetMsg) pinMessage(contextMenuTargetMsg.id);
});
document.getElementById('ctx-delete').addEventListener('click', () => {
  if (contextMenuTargetMsg) deleteMessageForEveryone(contextMenuTargetMsg.id);
});

// Pin Banner close/unpin action
document.getElementById('unpin-btn').addEventListener('click', (e) => {
  e.stopPropagation();
  if (pinnedMessageBar.dataset.msgId) {
    socket.emit('pin-message', { room: currentRoom, messageId: pinnedMessageBar.dataset.msgId });
  }
});

// --- 4. Admin Portal Functionality ---
function openAdminPortal() {
  const adminPortalModal = document.getElementById('admin-portal-modal');
  const adminCurrentPasscodeTxt = document.getElementById('admin-current-passcode-txt');
  const adminOtpStatusTxt = document.getElementById('admin-otp-status-txt');
  const adminNewPasscode = document.getElementById('admin-new-passcode');
  const adminSettingsForm = document.getElementById('admin-settings-form');
  const adminOtpVerificationPanel = document.getElementById('admin-otp-verification-panel');
  const adminOtpInput = document.getElementById('admin-otp-input');
  const adminPortalMessage = document.getElementById('admin-portal-message');

  if (!adminPortalModal) return;

  // Clear messages & fields
  adminPortalMessage.className = 'admin-portal-message';
  adminPortalMessage.textContent = '';
  if (adminNewPasscode) adminNewPasscode.value = '';
  if (adminOtpInput) adminOtpInput.value = '';
  if (adminOtpVerificationPanel) adminOtpVerificationPanel.classList.add('hidden');
  if (adminSettingsForm) adminSettingsForm.classList.remove('hidden');

  // Open modal
  adminPortalModal.classList.remove('hidden');

  // Fetch current config
  fetch(`${SOCKET_URL}/api/v1/sys/meta`)
    .then(res => res.json())
    .then(data => {
      if (adminCurrentPasscodeTxt) adminCurrentPasscodeTxt.textContent = data.currentPasscode;
      if (adminOtpStatusTxt) adminOtpStatusTxt.textContent = 'Permanently Enabled';
    })
    .catch(err => {
      console.error('Failed to load admin config:', err);
      if (adminPortalMessage) {
        adminPortalMessage.className = 'admin-portal-message error';
        adminPortalMessage.textContent = 'Failed to load configuration from server.';
      }
    });
}

// Bind admin close and submission buttons
document.addEventListener('DOMContentLoaded', () => {
  const adminPortalModal = document.getElementById('admin-portal-modal');
  const adminCloseBtn = document.getElementById('admin-close-btn');
  const adminSaveBtn = document.getElementById('admin-save-btn');
  const adminVerifyBtn = document.getElementById('admin-verify-btn');
  searchInput = document.getElementById('search-input');

  // Trigger Admin via search SHUBHAM + Enter
  if (searchInput) {
    searchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const val = searchInput.value.trim().toUpperCase();
        if (val === 'SHUBHAM') {
          e.preventDefault();
          searchInput.value = '';
          openAdminPortal();
        }
      }
    });
  }

  if (adminCloseBtn && adminPortalModal) {
    adminCloseBtn.addEventListener('click', () => {
      adminPortalModal.classList.add('hidden');
    });
  }

  if (adminSaveBtn) {
    adminSaveBtn.addEventListener('click', () => {
      const adminNewPasscode = document.getElementById('admin-new-passcode');
      const adminPortalMessage = document.getElementById('admin-portal-message');
      const adminSettingsForm = document.getElementById('admin-settings-form');
      const adminOtpVerificationPanel = document.getElementById('admin-otp-verification-panel');

      if (!adminNewPasscode || !adminNewPasscode.value.trim()) {
        adminPortalMessage.className = 'admin-portal-message error';
        adminPortalMessage.textContent = 'Please enter a valid passcode.';
        return;
      }

      adminPortalMessage.className = 'admin-portal-message';
      adminPortalMessage.textContent = 'Processing request...';

      fetch(`${SOCKET_URL}/api/v1/sys/req`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          newPasscode: adminNewPasscode.value.trim()
        })
      })
      .then(res => res.json())
      .then(data => {
        if (data.error) {
          adminPortalMessage.className = 'admin-portal-message error';
          adminPortalMessage.textContent = data.error;
          return;
        }

        if (data.otpRequired) {
          adminPortalMessage.className = 'admin-portal-message success';
          adminPortalMessage.textContent = data.message;
          if (adminSettingsForm) adminSettingsForm.classList.add('hidden');
          if (adminOtpVerificationPanel) adminOtpVerificationPanel.classList.remove('hidden');
        }
      })
      .catch(err => {
        console.error(err);
        adminPortalMessage.className = 'admin-portal-message error';
        adminPortalMessage.textContent = 'Request failed. Please try again.';
      });
    });
  }

  if (adminVerifyBtn) {
    adminVerifyBtn.addEventListener('click', () => {
      const adminOtpInput = document.getElementById('admin-otp-input');
      const adminPortalMessage = document.getElementById('admin-portal-message');
      const adminSettingsForm = document.getElementById('admin-settings-form');
      const adminOtpVerificationPanel = document.getElementById('admin-otp-verification-panel');
      const adminNewPasscode = document.getElementById('admin-new-passcode');

      if (!adminOtpInput || !adminOtpInput.value.trim()) {
        adminPortalMessage.className = 'admin-portal-message error';
        adminPortalMessage.textContent = 'Please enter the 6-digit OTP code.';
        return;
      }

      adminPortalMessage.className = 'admin-portal-message';
      adminPortalMessage.textContent = 'Verifying OTP...';

      fetch(`${SOCKET_URL}/api/v1/sys/confirm`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ otp: adminOtpInput.value.trim() })
      })
      .then(res => res.json())
      .then(data => {
        if (data.error) {
          adminPortalMessage.className = 'admin-portal-message error';
          adminPortalMessage.textContent = data.error;
          return;
        }

        adminPortalMessage.className = 'admin-portal-message success';
        adminPortalMessage.textContent = data.message;

        // Reset display
        if (adminSettingsForm) adminSettingsForm.classList.remove('hidden');
        if (adminOtpVerificationPanel) adminOtpVerificationPanel.classList.add('hidden');

        // Refresh configuration displays
        const adminCurrentPasscodeTxt = document.getElementById('admin-current-passcode-txt');
        if (adminCurrentPasscodeTxt) adminCurrentPasscodeTxt.textContent = adminNewPasscode.value.trim();
      })
      .catch(err => {
        console.error(err);
        adminPortalMessage.className = 'admin-portal-message error';
        adminPortalMessage.textContent = 'OTP verification failed. Please try again.';
      });
    });
  }
});


